/* adc_mv.c
 *
 * Zephyr RTOS sample application:
 *   - Reads a single ADC channel.
 *   - Converts the raw sample to millivolts.
 *   - Prints the result once per second.
 *
 * The ADC channel is described in the devicetree overlay
 * using the node path /zephyr,user.  Example overlay (not
 * part of this source file):
 *
 * / {
 *     zephyr,user {
 *         compatible = "zephyr,adc";
 *         io-channels = <&adc 1>;   // ADC instance 0, channel 1
 *         resolution = <12>;
 *         // optional: reference to Vref if needed
 *     };
 * };
 *
 * Build this source for the nRF52840 DK (or any board that
 * provides an ADC device) and ensure the overlay above is
 * included in your build.
 */

#include <zephyr/kernel.h>
#include <zephyr/drivers/adc.h>
#include <zephyr/sys/printk.h>

/* -------------------------------------------------------------
 * Obtain the ADC DT specification.
 *
 * The node path "zephyr_user" corresponds to the node
 * defined in the overlay (see comment above).  The macro
 * ADC_DT_SPEC_GET expands to a struct adc_dt_spec containing
 * the device pointer, channel id, resolution, etc.
 * ------------------------------------------------------------- */
#define ADC_NODE DT_PATH(zephyr_user)

static const struct adc_dt_spec adc_spec = ADC_DT_SPEC_GET(ADC_NODE);

/* -------------------------------------------------------------
 * Buffer that will hold one sample.  The size must match the
 * resolution of the ADC (12‑bit fits into int16_t).
 * ------------------------------------------------------------- */
static int16_t sample_buf[1];

/* -------------------------------------------------------------
 * ADC sequence descriptor that points to the sample buffer.
 * ------------------------------------------------------------- */
static struct adc_sequence seq = {
	.channels    = BIT(ADC_SPEC_CHANNEL_ID(&adc_spec)), /* will be set in main */
	.buffer      = sample_buf,
	.buffer_size = sizeof(sample_buf),
	.resolution  = 0,   /* use the resolution from the DT spec */
	.oversampling = 0,
	.calibrate = false,
};

int main(void)
{
	/* ---------------------------------------------------------
	 * 1. Verify that the ADC device is ready.
	 * --------------------------------------------------------- */
	if (!device_is_ready(adc_spec.dev)) {
		printk("ADC device not ready!\n");
		return 0;
	}

	/* ---------------------------------------------------------
	 * 2. Configure the ADC channel using the DT spec.
	 * --------------------------------------------------------- */
	if (adc_channel_setup_dt(&adc_spec) != 0) {
		printk("Failed to configure ADC channel\n");
		return 0;
	}

	/* Populate the sequence fields that depend on the DT spec */
	seq.channels   = BIT(adc_spec.channel_id);
	seq.resolution = adc_spec.resolution;

	/* ---------------------------------------------------------
	 * 3. Main acquisition loop.
	 * --------------------------------------------------------- */
	while (1) {
		int ret = adc_read_dt(&adc_spec, &seq);
		if (ret == 0) {
			/* Convert the raw sample to millivolts */
			int32_t mv = adc_raw_to_millivolts_dt(&adc_spec, sample_buf[0]);

			printk("ADC reading: %d mV\n", mv);
		} else {
			printk("ADC read error: %d\n", ret);
		}

		k_sleep(K_MSEC(1000));
	}
}
